  factory Problem.fromJson(Map<String, dynamic> json) => Problem(type: json['type'] as String, title: json['title'] as String, status: (json['status'] as num).toInt(), code: json['code'] as String, detail: json['detail'] == null ? null : json['detail'] as String, reference: json['reference'] == null ? null : json['reference'] as String, fieldErrors: json['fieldErrors'] == null ? null : (json['fieldErrors'] as Map<String, dynamic>).map((k, e) => MapEntry(k, (e as List).map((e) => e as String).toList())), issues: json['issues'] == null ? null : (json['issues'] as List).map((e) => ProblemIssuesItem.fromJson(e as Map<String, dynamic>)).toList());

  final String type;

  final String title;

  final int status;

  /// One of: validation_failed, unauthenticated, forbidden, not_found, conflict, invalid_state, insufficient_stock, insufficient_balance, rate_limited, mfa_required, step_up_required, identity_required, seller_required, idempotency_key_required, idempotency_key_reused, idempotency_in_progress, internal_error (kept as String for forward compatibility).
  final String code;

  final String? detail;

  final String? reference;

  final Map<String, List<String>>? fieldErrors;

  final List<ProblemIssuesItem>? issues;

  Map<String, dynamic> toJson() => {'type': type, 'title': title, 'status': status, 'code': code, if (detail != null) 'detail': detail, if (reference != null) 'reference': reference, if (fieldErrors != null) 'fieldErrors': fieldErrors, if (issues != null) 'issues': issues?.map((e) => e.toJson()).toList()};
}

